CREATE TABLE profile_transition_schema_v1(singleton INTEGER PRIMARY KEY CHECK(singleton=1),version INTEGER NOT NULL CHECK(version=1));
INSERT INTO profile_transition_schema_v1 VALUES(1,1);
CREATE TABLE profile_selection_v1(singleton INTEGER PRIMARY KEY CHECK(singleton=1),root TEXT NOT NULL CHECK(length(CAST(root AS BLOB))<=131072),generation INTEGER NOT NULL CHECK(generation>=0 AND generation<=9007199254740991),mode TEXT NOT NULL CHECK(mode IN ('legacy_current','reader_only')));
CREATE TABLE profile_transitions_v1(id TEXT PRIMARY KEY CHECK(length(id)=36),original TEXT NOT NULL CHECK(length(CAST(original AS BLOB))<=131072),expected_generation INTEGER NOT NULL CHECK(expected_generation>=0 AND expected_generation<=9007199254740991),inventory_hash TEXT NOT NULL CHECK(length(inventory_hash)=64),state TEXT NOT NULL CHECK(state IN ('prepared','preserved','staged','active','rolled_back')),snapshot TEXT CHECK(snapshot IS NULL OR length(CAST(snapshot AS BLOB))<=1024),candidate TEXT CHECK(candidate IS NULL OR length(CAST(candidate AS BLOB))<=262144),activation_generation INTEGER,rollback_generation INTEGER);
CREATE TABLE profile_activation_receipts_v1(id TEXT PRIMARY KEY CHECK(length(id)=36),operation TEXT NOT NULL CHECK(length(operation)=36),kind TEXT NOT NULL CHECK(kind IN ('activation','rollback')),from_generation INTEGER NOT NULL,to_generation INTEGER NOT NULL,selected_root TEXT NOT NULL CHECK(length(CAST(selected_root AS BLOB))<=131072),selected_mode TEXT NOT NULL CHECK(selected_mode IN ('legacy_current','reader_only')),UNIQUE(operation,kind));
